; misses.asm -- chapter 33: a turn too many
; generated by gen33.py
        INCLUDE "msx.inc"
        OUTPUT "misses.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
ticks   EQU VARS                ; frames counted by isr
last    EQU VARS + 1            ; ticks, the last time the logic looked
k       EQU VARS + 2            ; the work last done, 0 to 7
turns   EQU VARS + 3            ; fits.asm, misses.asm: the work's turns
acc     EQU VARS + 5            ; speed.asm: 256ths of a pixel not yet moved
speed   EQU VARS + 7            ; speed.asm: 256ths of a pixel a frame
copy    EQU $C400               ; the herd's attributes, 128 bytes
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
; fits.asm with one turn more: 2,221 turns at 50 Hz and 1,833 at 60 Hz.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $3800        ; the figure's four patterns
        ld hl, figure
        ld c, VDP_DATA
        ld b, 32
        otir
        ld hl, herd             ; the herd's attributes, to the copy ...
        ld de, copy
        ld bc, 128
        ldir
        VRAM_WRITE $1B00        ; ... and to the VDP
        ld hl, copy
        ld c, VDP_DATA
        ld b, 128
        otir
        xor a
        ld (ticks), a
        ld (last), a
        ld a, 7
        ld (k), a               ; the first work is the first of the eight
        ld a, ($002B)           ; bit 7 is 1 on a 50 Hz machine (chapter 4)
        rla
        ld hl, 1833             ; 60 Hz ...
        jr nc, .rturns
        ld hl, 2221             ; ... and 50 Hz
.rturns:ld (turns), hl
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        VDP_REG 1, $E2          ; the display on, the frame's signal, 16 x 16
        in a, (VDP_CTRL)        ; no signal left over
        ei
main:   halt                    ; wait for the frame
        di
        ld a, 4                 ; dark blue
        out (VDP_CTRL), a
        ld a, $87
m0:     out (VDP_CTRL), a       ; R#7: the herd sent
        ei
        di
        ld a, low $1B00
        out (VDP_CTRL), a
        ld a, high $1B00 | $40
        out (VDP_CTRL), a       ; the attribute table, for writing
        ei
        ld hl, copy
        ld c, VDP_DATA
        ld b, 128
        otir                    ; the herd: 127 x 23 + 18 T-states
s1:     di
        ld a, 7                 ; cyan
        out (VDP_CTRL), a
        ld a, $87
m1:     out (VDP_CTRL), a       ; R#7: the logic
        ei
        ld a, (ticks)           ; the frames counted by isr ...
        ld hl, last
        ld b, a
        sub (hl)                ; ... since the last time: A
        ld (hl), b              ; and this is the last time now
        ld b, a
.steps: push bc
        call step               ; a pixel for every frame
        pop bc
        djnz .steps
        ld bc, (turns)          ; the work's turns, for the machine
.work:  dec bc                  ;  7
        ld a, b                 ;  5
        or c                    ;  5
        jr nz, .work            ; 13: 30 T-states a turn
        di
        ld a, 15                ; white
        out (VDP_CTRL), a
        ld a, $87
m2:     out (VDP_CTRL), a       ; R#7: waiting
        ei
        jr main

; isr: every frame, a frame counted. Keeps AF
isr:    push af                 ; 12
        in a, (VDP_CTRL)        ; 12  the status: the signal down
        ld a, (ticks)           ; 14
        inc a                   ;  5
        ld (ticks), a           ; 14
        pop af                  ; 11
        ei                      ;  5
        ret                     ; 11

; step: the herd a pixel on, in the copy: even rows of four a pixel right, odd
; rows a pixel left
step:   ld hl, copy + 1         ; sprite 0's X
        ld de, 4
        ld c, 4
.row:   ld b, 4
.right: inc (hl)                ; X + 1
        add hl, de
        djnz .right
        ld b, 4
.left:  dec (hl)                ; X - 1
        add hl, de
        djnz .left
        dec c
        jr nz, .row
        ret
figure:                         ; chapter 26's figure, 16 x 16
        db $03, $07, $05, $07, $02, $1F, $3F, $37
        db $37, $37, $07, $06, $06, $06, $0E, $0E
        db $C0, $E0, $A0, $E0, $40, $F8, $FC, $EC
        db $EC, $EC, $E0, $60, $60, $60, $70, $70
herd:                           ; 32 figures, eight rows of four
        db $06, $00, $00, $01
        db $06, $40, $00, $04
        db $06, $80, $00, $01
        db $06, $C0, $00, $04
        db $1D, $10, $00, $04
        db $1D, $50, $00, $01
        db $1D, $90, $00, $04
        db $1D, $D0, $00, $01
        db $34, $20, $00, $01
        db $34, $60, $00, $04
        db $34, $A0, $00, $01
        db $34, $E0, $00, $04
        db $4B, $30, $00, $04
        db $4B, $70, $00, $01
        db $4B, $B0, $00, $04
        db $4B, $F0, $00, $01
        db $62, $40, $00, $01
        db $62, $80, $00, $04
        db $62, $C0, $00, $01
        db $62, $00, $00, $04
        db $79, $50, $00, $04
        db $79, $90, $00, $01
        db $79, $D0, $00, $04
        db $79, $10, $00, $01
        db $90, $60, $00, $01
        db $90, $A0, $00, $04
        db $90, $E0, $00, $01
        db $90, $20, $00, $04
        db $A7, $70, $00, $04
        db $A7, $B0, $00, $01
        db $A7, $F0, $00, $04
        db $A7, $30, $00, $01
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
